L000114	\title{
L000115	Quantum Critical Dynamics Induced by Topological Zero Modes
L000116	}
L000117	
L000118	\author{Ilia Komissarov}
L000119	\email{i.komissarov@columbia.edu}
L000120	\affiliation{Department of Physics, Columbia University, New York, NY 10027, USA}
